// Rename the form's column headers to the names the rules use.
return $input.all().map(i => ({ json: {
  timestamp: i.json['Timestamp'], donor: i.json['Donor name'], email: i.json['Email'],
  amount: Number(i.json['Amount']), currency: i.json['Currency'], fund: i.json['Fund type'],
  message: i.json['Message'], row: i.json['row_number'] } }));

// Receipt number, fund check and trustee flags. Change LARGE_GIFT here only.
const LARGE_GIFT = 1000;
const FUNDS = ['Zakat', 'Sadaqah', 'Waqf', 'General'];
return $input.all().map((item, i) => {
  const d = item.json;
  const row = d.row ?? (i + 2);
  const fundKnown = FUNDS.includes(d.fund);
  const hasEmail = /@/.test(d.email || '');
  const reasons = [];
  if (Number(d.amount) >= LARGE_GIFT) reasons.push('Large gift: please check the payment and thank the donor personally');
  if (!fundKnown) reasons.push('Fund not recognised: confirm with the donor before it is used');
  if (!hasEmail) reasons.push('No email address: thank the donor another way');
  return { json: {
    ...d,
    receipt: 'CHF-2026-' + String(row).padStart(6, '0'),
    fundKnown, hasEmail,
    sendThankYou: fundKnown && hasEmail,
    trusteeAlert: reasons.length > 0,
    trusteeReasons: reasons.join('; '),
  }};
});

// Builds the fund-specific thank-you email. Confirm the Zakat wording with the charity's Shariah adviser.
const WINE = '#4a1424', RED = '#b3202a', INK = '#1d1416', MUTED = '#5f5456', LINE = '#d9d4d5';
const FUND_TEXT = {
  Zakat: "We keep all Zakat in a separate account, apart from our other funds. Your Zakat will be given only to people who are eligible to receive it, within the eight categories (asnaf) named in the Qur'an (Surah At-Tawbah, 9:60). We do not use Zakat to pay our running costs.",
  Sadaqah: 'Your Sadaqah supports our general programmes, including food parcels, school supplies and emergency help for families.',
  Waqf: 'Your gift joins our Waqf fund. The principal is preserved, and only the returns it earns are spent on our programmes, so your gift keeps giving.',
  General: 'Your gift supports our work wherever the need is greatest, including the costs of running our programmes well.',
};
const cell = 'border:1px solid ' + LINE + ';padding:9px';
const out = [];
for (const item of $input.all()) {
  const d = item.json;
  if (!d.sendThankYou) continue;
  const amount = Number(d.amount).toFixed(2);
  const first = String(d.donor || '').split(' ')[0];
  const label = d.fund === 'General' ? 'gift' : d.fund;
  const html =
    '<div style="font-family:Helvetica,Arial,sans-serif;color:' + INK + ';max-width:600px;margin:0 auto;border:1px solid ' + LINE + '">' +
    '<div style="background:' + WINE + ';color:#fff;padding:22px 28px"><div style="font-family:Georgia,serif;font-size:20px;letter-spacing:2px">CRESCENT HOPE FOUNDATION</div>' +
    '<div style="width:48px;height:2px;background:' + RED + ';margin-top:8px"></div></div>' +
    '<div style="padding:26px 28px"><h1 style="font-family:Georgia,serif;color:' + WINE + ';font-size:24px;margin:0 0 14px">Thank you for your ' + label + '</h1>' +
    '<p>As-salamu alaykum ' + first + ',</p><p>Thank you for trusting us with your ' + label + '. We have received it safely.</p>' +
    '<p>May Allah accept it from you and reward you.</p>' +
    '<table style="width:100%;border-collapse:collapse;margin:16px 0;font-size:14px">' +
    '<tr><td style="' + cell + ';color:' + MUTED + '">Receipt number</td><td style="' + cell + '"><b>' + d.receipt + '</b></td></tr>' +
    '<tr><td style="' + cell + ';color:' + MUTED + '">Amount</td><td style="' + cell + '"><b>' + d.currency + ' ' + amount + '</b></td></tr>' +
    '<tr><td style="' + cell + ';color:' + MUTED + '">Fund</td><td style="' + cell + '"><b>' + d.fund + '</b></td></tr></table>' +
    '<p style="font-size:13px;color:' + RED + ';margin:0 0 4px;font-weight:bold;letter-spacing:1px">HOW YOUR ' + label.toUpperCase() + ' IS USED</p>' +
    '<p>' + FUND_TEXT[d.fund] + '</p><p>Please keep this email for your records.</p>' +
    '<p>With thanks,<br>The Crescent Hope Foundation team</p></div>' +
    '<div style="border-top:1px solid ' + LINE + ';padding:14px 28px;font-size:12px;color:' + MUTED + '">This email is an acknowledgement of your gift. It is not a tax receipt. Crescent Hope Foundation (a fictional organisation).</div></div>';
  out.push({ json: { to: d.email, subject: 'Your ' + label + ' has been received: receipt ' + d.receipt, receipt: d.receipt, fund: d.fund, html } });
}
return out;

// One alert listing every gift a trustee should look at.
const flagged = $input.all().map(i => i.json).filter(d => d.trusteeAlert);
if (!flagged.length) return [];
const lines = flagged.map(d => d.receipt + ' | ' + d.donor + ' | ' + d.currency + ' ' + Number(d.amount).toFixed(2) + ' | ' + d.fund + ' | ' + d.trusteeReasons);
return [{ json: { to: 'trustee@example.org', subject: 'Gifts to check: ' + flagged.length, count: flagged.length,
  text: 'As-salamu alaykum,\n\nPlease check these gifts:\n\n' + lines.join('\n') } }];
